import{_ as l,a0 as o,w as p,s as r,I as a,x as t,a1 as e,A as n,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Sway 中设置多个显示器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Sway 中设置多个显示器 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Sway 中设置多个显示器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Sway 中设置多个显示器 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20200108 How to setup multiple monitors in sway","title":"如何在 Sway 中设置多个显示器","tag":"202001","desc":""},"relativePath":"202001/20200108 How to setup multiple monitors in sway.md","filePath":"[post].md"}'),u={name:"202001/20200108 How to setup multiple monitors in sway.md"};function g(h,s,k,m,f,b){const i=o("Link");return p(),r("div",null,[s[23]||(s[23]=a("h1",{id:"如何在-sway-中设置多个显示器",tabindex:"-1"},[t("如何在 Sway 中设置多个显示器 "),a("a",{class:"header-anchor",href:"#如何在-sway-中设置多个显示器","aria-label":"Permalink to “如何在 Sway 中设置多个显示器”"},"​")],-1)),s[24]||(s[24]=a("p",null,[a("img",{src:"https://fedoramagazine.org/wp-content/uploads/2020/01/sway-multiple-monitors-816x345.png",alt:""})],-1)),a("p",null,[s[1]||(s[1]=t("Sway 是一种平铺式 Wayland 合成器，具有与 ",-1)),e(i,{href:"https://fedoramagazine.org/getting-started-i3-window-manager/"},{default:n(()=>[...s[0]||(s[0]=[t("i3 X11 窗口管理器",-1)])]),_:1}),s[2]||(s[2]=t("相同的功能、外观和工作流程。由于 Sway 使用 Wayland 而不是 X11，因此就不能一如既往地使用设置 X11 的工具。这包括 ",-1)),s[3]||(s[3]=a("code",null,"xrandr",-1)),s[4]||(s[4]=t(" 之类的工具，这些工具在 X11 窗口管理器或桌面中用于设置显示器。这就是为什么必须通过编辑 Sway 配置文件来设置显示器的原因，这就是本文的目的。",-1))]),s[25]||(s[25]=d(`<h3 id="获取你的显示器-id" tabindex="-1">获取你的显示器 ID <a class="header-anchor" href="#获取你的显示器-id" aria-label="Permalink to “获取你的显示器 ID”">​</a></h3><p>首先，你必须获得 Sway 用来指代显示器的名称。你可以通过运行以下命令进行操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ swaymsg -t get_outputs</span></span></code></pre></div><p>你将获得所有显示器的相关信息，每个显示器都用空行分隔。</p><p>你必须查看每个部分的第一行，以及 <code>Output</code> 之后的内容。例如，当你看到 <code>Output DVI-D-1 &#39;Philips Consumer Electronics Company&#39;</code> 之类的行时，则该输出 ID 为 <code>DVI-D-1</code>。注意这些 ID 及其所属的物理监视器。</p><h3 id="编辑配置文件" tabindex="-1">编辑配置文件 <a class="header-anchor" href="#编辑配置文件" aria-label="Permalink to “编辑配置文件”">​</a></h3><p>如果你之前没有编辑过 Sway 配置文件，则必须通过运行以下命令将其复制到主目录中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r /etc/sway/config ~/.config/sway/config</span></span></code></pre></div><p>现在，默认配置文件位于 <code>~/.config/sway</code> 中，名为 <code>config</code>。你可以使用任何文本编辑器进行编辑。</p><p>现在你需要做一点数学。想象有一个网格，其原点在左上角。X 和 Y 坐标的单位是像素。Y 轴反转。这意味着，例如，如果你从原点开始，向右移动 100 像素，向下移动 80 像素，则坐标将为 <code>(100, 80)</code>。</p><p>你必须计算最终显示在此网格上的位置。显示器的位置由左上方的像素指定。例如，如果我们要使用名称为“HDMI1”且分辨率为 1920×1080 的显示器，并在其右侧使用名称为 “eDP1” 且分辨率为 1600×900 的笔记本电脑显示器，则必须在配置文件中键入 ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>output HDMI1 pos 0 0</span></span>
<span class="line"><span>output eDP1 pos 1920 0</span></span></code></pre></div><p>你还可以使用 <code>res</code> 选项手动指定分辨率：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>output HDMI1 pos 0 0 res 1920x1080</span></span>
<span class="line"><span>output eDP1 pos 1920 0 res 1600x900</span></span></code></pre></div><h3 id="将工作空间绑定到显示器上" tabindex="-1">将工作空间绑定到显示器上 <a class="header-anchor" href="#将工作空间绑定到显示器上" aria-label="Permalink to “将工作空间绑定到显示器上”">​</a></h3><p>与多个监视器一起使用 Sway 在工作区管理中可能会有些棘手。幸运的是，你可以将工作区绑定到特定的显示器上，因此你可以轻松地切换到该显示器并更有效地使用它。只需通过配置文件中的 <code>workspace</code> 命令即可完成。例如，如果要绑定工作区 1 和 2 到显示器 “DVI-D-1”，绑定工作区 8 和 9 到显示器 “HDMI-A-1”，则可以使用以下方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>workspace 1 output DVI-D-1</span></span>
<span class="line"><span>workspace 2 output DVI-D-1</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>workspace 8 output HDMI-A-1</span></span>
<span class="line"><span>workspace 9 output HDMI-A-1</span></span></code></pre></div>`,18)),a("p",null,[s[6]||(s[6]=t("就是这样。这就在 Sway 中多显示器设置的基础知识。可以在 ",-1)),e(i,{href:"https://github.com/swaywm/sway/wiki#Wiki#Multihead"},{default:n(()=>[...s[5]||(s[5]=[t("https://github.com/swaywm/sway/wiki#Wiki#Multihead",-1)])]),_:1}),s[7]||(s[7]=t(" 中找到更详细的指南。",-1))]),s[26]||(s[26]=a("hr",null,null,-1)),a("p",null,[s[9]||(s[9]=t("via: ",-1)),e(i,{href:"https://fedoramagazine.org/how-to-setup-multiple-monitors-in-sway/"},{default:n(()=>[...s[8]||(s[8]=[t("https://fedoramagazine.org/how-to-setup-multiple-monitors-in-sway/",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=t("作者：",-1)),e(i,{href:"https://fedoramagazine.org/author/arte219/"},{default:n(()=>[...s[10]||(s[10]=[t("arte219",-1)])]),_:1}),s[15]||(s[15]=t(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[11]||(s[11]=[t("lujun9972",-1)])]),_:1}),s[16]||(s[16]=t(" 译者：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[12]||(s[12]=[t("wxy",-1)])]),_:1}),s[17]||(s[17]=t(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[13]||(s[13]=[t("wxy",-1)])]),_:1})]),a("p",null,[s[20]||(s[20]=t("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[18]||(s[18]=[t("LCTT",-1)])]),_:1}),s[21]||(s[21]=t(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[19]||(s[19]=[t("Linux中国",-1)])]),_:1}),s[22]||(s[22]=t(" 荣誉推出",-1))])])}const x=l(u,[["render",g]]);export{C as __pageData,x as default};
